choose.when:
UPDATE fg_doc_item AS target SET seq=v.seq, qty=v.qty, prd_receipt_item_id=v.receipt_item_id, order_item_id=v.order_item_id, price=v.price, amount=v.amount, remark=v.remark FROM (VALUES
(CAST(#{i.id} AS bigint), CAST(#{i.styleSkuId} AS bigint), CAST(#{i.seq} AS integer), CAST(#{i.qty} AS integer), CAST(#{i.prdReceiptItemId,jdbcType=BIGINT} AS bigint), CAST(#{i.orderItemId,jdbcType=BIGINT} AS bigint), CAST(#{i.price,jdbcType=NUMERIC} AS numeric), CAST(#{i.amount,jdbcType=NUMERIC} AS numeric), CAST(#{i.remark,jdbcType=VARCHAR} AS varchar))
) AS v(id,sku_id,seq,qty,receipt_item_id,order_item_id,price,amount,remark) WHERE target.doc_id=#{docId} AND target.id=v.id AND target.style_sku_id=v.sku_id
